"""Rule-based error classifier v2 for ALFWorld failure trajectories.

Independent of correction span to avoid tautological correlation with P1 metric.
Designed as control/comparison against LLM-based classification.

Input: Same format as classify_errors.py (failure JSONL + expert JSONL)
Output: Same format as classify_errors.py (classified JSONL with error_type)

Usage:
    python src/classify_errors_rulebased.py \
        --failure_dir data/trajectories_v6_icl_cuda0/ \
        --expert_file data/alfworld_sft.json \
        --output_file outputs/classified_v6_rulebased.jsonl
"""

import argparse
import json
import logging
import re
from collections import Counter
from pathlib import Path

from classify_errors import (
    normalize_game_file,
    extract_actions_expert,
    extract_actions_model,
    extract_task_desc,
    compute_divergence,
    load_expert_data,
    load_failure_trajectories,
)
from post_process_trajectories import (
    detect_csf,
    TERMINATION_ACTIONS,
    find_last_task_start,
    extract_actions_observations,
)

logger = logging.getLogger("classify_errors_rulebased")

_ACTION_RE = re.compile(r"Action:\s*(.+?)$", re.MULTILINE)

# Task type -> required subtask verbs
REQUIRED_SUBTASKS = {
    "pick_clean_then_place": ["clean"],
    "pick_heat_then_place": ["heat"],
    "pick_cool_then_place": ["cool"],
    "look_at_obj_in_light": ["use"],
    "examine_in_light": ["use"],
}


# ---------------------------------------------------------------------------
# Action parsing
# ---------------------------------------------------------------------------

def parse_action(action_str: str) -> dict:
    """Parse ALFWorld action into verb + arguments."""
    a = action_str.strip().lower()

    m = re.match(r"go to (\w+)\s*(\d+)?", a)
    if m:
        return {"verb": "go to", "object": m.group(1),
                "instance": m.group(2) or ""}

    m = re.match(r"take (\w+)\s*(\d+)?\s+from\s+(\w+)\s*(\d+)?", a)
    if m:
        return {"verb": "take", "object": m.group(1),
                "instance": m.group(2) or "",
                "receptacle": m.group(3), "rec_instance": m.group(4) or ""}

    m = re.match(r"put (\w+)\s*(\d+)?\s+(?:in|on|in/on)\s+(\w+)\s*(\d+)?", a)
    if m:
        return {"verb": "put", "object": m.group(1),
                "instance": m.group(2) or "",
                "receptacle": m.group(3), "rec_instance": m.group(4) or ""}

    m = re.match(r"(clean|heat|cool)\s+(\w+)\s*(\d+)?\s+with\s+(\w+)\s*(\d+)?", a)
    if m:
        return {"verb": m.group(1), "object": m.group(2),
                "instance": m.group(3) or "",
                "receptacle": m.group(4), "rec_instance": m.group(5) or ""}

    m = re.match(r"use\s+(\w+)\s*(\d+)?", a)
    if m:
        return {"verb": "use", "object": m.group(1),
                "instance": m.group(2) or ""}

    m = re.match(r"(open|close|toggle|examine|look)\s+(\w+)\s*(\d+)?", a)
    if m:
        return {"verb": m.group(1), "object": m.group(2),
                "instance": m.group(3) or ""}

    return {"verb": a, "object": "", "instance": ""}


# ---------------------------------------------------------------------------
# Rule functions — each returns a classification dict or None
# ---------------------------------------------------------------------------

def rule_pcb(trajectory: dict) -> dict | None:
    """Premature completion belief: agent repeatedly issues termination actions
    while the task is incomplete."""
    if "csf_details" in trajectory:
        return {
            "error_type": "verification",
            "sub_type": "premature_completion_belief",
            "rule_fired": "rule_pcb",
            "reasoning": "Agent repeatedly attempted termination actions before task completion.",
        }
    csf = detect_csf(trajectory)
    if csf.get("is_csf"):
        return {
            "error_type": "verification",
            "sub_type": "premature_completion_belief",
            "rule_fired": "rule_pcb",
            "reasoning": f"CSF detected: {csf.get('term_count', 0)} consecutive termination actions.",
        }
    return None


def rule_wrong_object(expert_actions: list[dict], model_actions: list[dict],
                      div_info: dict) -> dict | None:
    """Same verb at divergence point but different target object."""
    div_step = div_info["divergence_step"] - 1
    if div_step >= len(expert_actions) or div_step >= len(model_actions):
        return None

    ep = parse_action(expert_actions[div_step]["action"])
    mp = parse_action(model_actions[div_step]["action"])

    if ep["verb"] != mp["verb"]:
        return None

    verb = ep["verb"]
    e_obj = ep.get("object", "")
    m_obj = mp.get("object", "")
    if not e_obj or not m_obj:
        return None

    if e_obj != m_obj:
        return {
            "error_type": "action",
            "sub_type": "wrong_object",
            "rule_fired": "rule_wrong_object",
            "reasoning": (f"Step {div_step+1}: '{verb}' targeted "
                          f"'{m_obj}' instead of '{e_obj}'."),
        }

    # Same object type, different instance
    e_inst = ep.get("instance", "")
    m_inst = mp.get("instance", "")
    if e_inst and m_inst and e_inst != m_inst:
        return {
            "error_type": "action",
            "sub_type": "wrong_instance",
            "rule_fired": "rule_wrong_instance",
            "reasoning": (f"Step {div_step+1}: went to "
                          f"'{m_obj} {m_inst}' instead of '{e_obj} {e_inst}'."),
        }

    # Same verb + same object, but different receptacle (take/put)
    if verb in ("take", "put"):
        e_rec = ep.get("receptacle", "")
        m_rec = mp.get("receptacle", "")
        if e_rec and m_rec and e_rec != m_rec:
            return {
                "error_type": "action",
                "sub_type": "wrong_receptacle",
                "rule_fired": "rule_wrong_receptacle",
                "reasoning": (f"Step {div_step+1}: used receptacle "
                              f"'{m_rec}' instead of '{e_rec}'."),
            }

    return None


